{
  "schemaVersion": "0.2",
  "slug": "date-picker",
  "name": "DatePicker",
  "family": "C",
  "status": "experimental",
  "purpose": "Picks a calendar date through an input with a month-grid popover; formatting uses Intl.",
  "scenarios": [
    "Choose a delivery date",
    "Set a report start date",
    "Book an appointment"
  ],
  "props": {
    "value": {
      "type": "string",
      "required": true,
      "description": "ISO date string yyyy-mm-dd or empty."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called with the ISO date on selection."
    },
    "label": {
      "type": "string",
      "required": true,
      "description": "Field label."
    },
    "locale": {
      "type": "string",
      "required": false,
      "description": "BCP 47 locale for Intl formatting.",
      "default": "en"
    },
    "previousMonthLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for previous month."
    },
    "nextMonthLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible label for next month."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "closed",
      "description": "Input only."
    },
    {
      "name": "open",
      "description": "Month grid visible."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "card",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not hand-format dates; use Intl.DateTimeFormat.",
    "Do not allow keyboard-inaccessible day cells."
  ],
  "a11y": {
    "role": "dialog",
    "keyboard": [
      "Escape closes the grid",
      "Tab moves through day buttons"
    ],
    "focus": "Day cells are buttons; focus returns to the input on close.",
    "labeling": "Field label names the input; month and year headline the grid.",
    "wcag": [
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Compact: block-end bottom sheet via viewport @container positioner (Dialog pattern). Medium/large: centered floating panel. Escape/backdrop dismiss. Field-inline calendar on large is future — do not claim it.",
    "breakpoints": {
      "compact": "Bottom sheet: full inline size, block-end dock, start-edge radii only.",
      "medium": "Centered floating calendar panel.",
      "large": "Centered floating calendar panel (inline-in-field not yet shipped)."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "date-picker",
    "states": [
      "closed",
      "open"
    ],
    "intents": [
      "pick-datetime"
    ]
  }
}

import { useId, useRef, useState } from 'react'
import './styles.css'

export interface DatePickerProps {
  value: string
  onChange: (isoDate: string) => void
  label: string
  locale?: string
  previousMonthLabel?: string
  nextMonthLabel?: string
  closeLabel?: string
  className?: string
}

const DAY_MS = 86_400_000
/** 2023-01-01 was a Sunday; anchor for Intl-derived weekday names. */
const SUNDAY = Date.UTC(2023, 0, 1)

function parseISODate(value: string | undefined): { year: number; month: number } {
  const parts = value?.split('-').map(Number) ?? []
  const now = new Date()
  return {
    year: parts[0] || now.getUTCFullYear(),
    month: parts[1] ? parts[1] - 1 : now.getUTCMonth(),
  }
}

function toISODate(year: number, month: number, day: number): string {
  return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`
}

function daysInMonth(year: number, month: number): number {
  return new Date(Date.UTC(year, month + 1, 0)).getUTCDate()
}

/** Locale first day of week normalized to 0 (Sunday) … 6 (Saturday). */
function firstDayOfWeek(locale: string): number {
  try {
    const info = (new Intl.Locale(locale) as { weekInfo?: { firstDay?: number } }).weekInfo
    return (info?.firstDay ?? 7) % 7
  } catch {
    return 0
  }
}

function weekdayNames(locale: string, firstDay: number): string[] {
  const format = new Intl.DateTimeFormat(locale, { weekday: 'short', timeZone: 'UTC' })
  return Array.from({ length: 7 }, (_, index) => format.format(new Date(SUNDAY + ((firstDay + index) % 7) * DAY_MS)))
}

export function DatePicker({
  value,
  onChange,
  label,
  locale = 'en',
  previousMonthLabel = 'Previous month',
  nextMonthLabel = 'Next month',
  closeLabel = 'Close calendar',
  className,
}: DatePickerProps) {
  const [open, setOpen] = useState(false)
  const [view, setView] = useState(() => parseISODate(value))
  const inputRef = useRef<HTMLInputElement>(null)
  const inputId = useId()
  const classes = ['cu-date-picker', className].filter(Boolean).join(' ')

  const dateFormat = new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeZone: 'UTC' })
  const monthFormat = new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric', timeZone: 'UTC' })
  const dayFormat = new Intl.NumberFormat(locale)
  const parsed = value ? new Date(`${value}T00:00:00Z`) : null
  const display = parsed && !Number.isNaN(parsed.getTime()) ? dateFormat.format(parsed) : ''
  const headline = monthFormat.format(new Date(Date.UTC(view.year, view.month, 1)))
  const firstDay = firstDayOfWeek(locale)
  const weekdays = weekdayNames(locale, firstDay)
  const leadingBlanks = (new Date(Date.UTC(view.year, view.month, 1)).getUTCDay() - firstDay + 7) % 7
  const dayCount = daysInMonth(view.year, view.month)
  const cells: (number | null)[] = [
    ...Array.from({ length: leadingBlanks }, () => null),
    ...Array.from({ length: dayCount }, (_, index) => index + 1),
  ]
  const weeks: (number | null)[][] = []
  for (let index = 0; index < cells.length; index += 7) {
    weeks.push(cells.slice(index, index + 7))
  }

  const close = () => {
    setOpen(false)
    inputRef.current?.focus()
  }

  const move = (delta: number) => {
    setView((current) => {
      const next = new Date(Date.UTC(current.year, current.month + delta, 1))
      return { year: next.getUTCFullYear(), month: next.getUTCMonth() }
    })
  }

  const pick = (day: number) => {
    onChange(toISODate(view.year, view.month, day))
    close()
  }

  return (
    <div className={classes} data-ai-role="date-picker" data-ai-intent="pick-datetime" data-ai-state={open ? 'open' : 'closed'}>
      <label className="cu-date-picker__label" htmlFor={inputId}>
        {label}
      </label>
      <div className="cu-date-picker__field">
        <input
          ref={inputRef}
          id={inputId}
          className="cu-date-picker__input"
          type="text"
          role="combobox"
          readOnly
          value={display}
          aria-expanded={open}
          aria-haspopup="dialog"
          onClick={() => {
            setView(parseISODate(value))
            setOpen(true)
          }}
          onKeyDown={(event) => {
            if (event.key === 'Escape') close()
            if (event.key === 'Enter' || event.key === ' ') {
              event.preventDefault()
              setView(parseISODate(value))
              setOpen(true)
            }
          }}
        />
        <button
          type="button"
          className="cu-date-picker__toggle"
          aria-label={label}
          onClick={() => {
            setView(parseISODate(value))
            setOpen((current) => !current)
          }}
        >
          <span aria-hidden="true">▾</span>
        </button>
      </div>
      {open ? (
        <div className="cu-date-picker__positioner">
          <button type="button" className="cu-date-picker__backdrop" aria-label={closeLabel} onClick={close} />
          <div
            className="cu-date-picker__popover"
            role="dialog"
            aria-label={headline}
            onKeyDown={(event) => {
              if (event.key === 'Escape') close()
            }}
          >
            <div className="cu-date-picker__header">
              <button type="button" className="cu-date-picker__nav" aria-label={previousMonthLabel} onClick={() => move(-1)}>
                <span aria-hidden="true">‹</span>
              </button>
              <span className="cu-date-picker__headline">{headline}</span>
              <button type="button" className="cu-date-picker__nav" aria-label={nextMonthLabel} onClick={() => move(1)}>
                <span aria-hidden="true">›</span>
              </button>
            </div>
            <div className="cu-date-picker__grid" role="grid" aria-label={headline}>
              <div className="cu-date-picker__weekdays" role="row">
                {weekdays.map((weekday, index) => (
                  <span key={weekday + index} className="cu-date-picker__weekday" role="columnheader">
                    {weekday}
                  </span>
                ))}
              </div>
              {weeks.map((week, weekIndex) => (
                <div key={weekIndex} className="cu-date-picker__week" role="row">
                  {week.map((day, dayIndex) =>
                    day === null ? (
                      <span
                        key={`blank-${weekIndex}-${dayIndex}`}
                        className="cu-date-picker__blank"
                        role="gridcell"
                        aria-hidden="true"
                      />
                    ) : (
                      <span
                        key={day}
                        className="cu-date-picker__cell"
                        role="gridcell"
                        aria-selected={value === toISODate(view.year, view.month, day)}
                      >
                        <button
                          type="button"
                          className="cu-date-picker__day"
                          aria-label={toISODate(view.year, view.month, day)}
                          onClick={() => pick(day)}
                        >
                          {dayFormat.format(day)}
                        </button>
                      </span>
                    ),
                  )}
                </div>
              ))}
            </div>
          </div>
        </div>
      ) : null}
    </div>
  )
}

.cu-date-picker {
  position: relative;
  display: grid;
  gap: var(--cu-space-1);
  color: var(--cu-color-fg-default);
}

.cu-date-picker__label {
  font-size: 0.82rem;
  font-weight: 700;
}

.cu-date-picker__field {
  display: flex;
  align-items: stretch;
}

.cu-date-picker__input {
  flex: 1 1 auto;
  min-inline-size: 0;
  min-block-size: 2.75rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-start-start-radius: var(--cu-radius-md);
  border-end-start-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-date-picker__toggle {
  min-inline-size: var(--cu-touch-target-min);
  border: 1px solid var(--cu-color-border-default);
  border-inline-start: 0;
  border-start-end-radius: var(--cu-radius-md);
  border-end-end-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-date-picker__input:focus-visible,
.cu-date-picker__toggle:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 1px;
}

/*
 * Appendix C morph: compact = bottom sheet; medium/large = floating panel.
 * Viewport-sized positioner is the @container (same pattern as Dialog).
 */
.cu-date-picker__positioner {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: end center;
  container-type: inline-size;
}

.cu-date-picker__backdrop {
  position: absolute;
  inset: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: color-mix(in srgb, var(--cu-color-background-inverse) 44%, transparent);
  cursor: pointer;
}

.cu-date-picker__popover {
  position: relative;
  z-index: 1;
  inline-size: 100%;
  max-block-size: min(90vh, 28rem);
  overflow: auto;
  margin-block-start: 0;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-start-start-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  border-start-end-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  background: var(--cu-color-background-default);
  box-shadow: 0 var(--cu-space-1) var(--cu-space-3) color-mix(in srgb, var(--cu-color-fg-default) 18%, transparent);
}

.cu-date-picker__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--cu-space-2);
  margin-block-end: var(--cu-space-2);
}

.cu-date-picker__headline {
  font-weight: 700;
}

.cu-date-picker__nav {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border: 0;
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

.cu-date-picker__nav:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

.cu-date-picker__grid {
  inline-size: 100%;
}

.cu-date-picker__weekdays,
.cu-date-picker__week {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
}

.cu-date-picker__weekday {
  padding-block: var(--cu-space-1);
  text-align: center;
  font-size: 0.82rem;
  font-weight: 700;
  color: color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent);
}

.cu-date-picker__cell,
.cu-date-picker__blank {
  display: flex;
  align-items: center;
  justify-content: center;
}

.cu-date-picker__day {
  min-inline-size: var(--cu-touch-target-min);
  min-block-size: var(--cu-touch-target-min);
  border: 0;
  border-radius: var(--cu-radius-sm);
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

@media (hover: hover) {
  .cu-date-picker__day:hover {
    background: color-mix(in srgb, var(--cu-color-palette-brand) 10%, var(--cu-color-background-default));
  }
}

.cu-date-picker__cell[aria-selected='true'] .cu-date-picker__day {
  background: var(--cu-color-palette-brand);
  color: var(--cu-color-fg-inverse);
}

.cu-date-picker__day:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
}

/* 48rem == breakpoint.tablet */
@container (min-width: 48rem) {
  .cu-date-picker__positioner {
    place-items: center;
  }

  .cu-date-picker__popover {
    inline-size: min(100%, 22rem);
    border-radius: var(--cu-radius-xl, var(--cu-radius-lg));
  }
}
